// ── Category color helper ─────────────────────────────────────────────────────────────────────────────
function getCategoryColor(cat: string) {
  if (cat === "ভালোবাসা") return { stripe: "#e74c3c", badge: "rgba(231,76,60,0.12)", text: "#c0392b" };
  if (cat === "বিচ্ছেদ") return { stripe: "#8e44ad", badge: "rgba(142,68,173,0.12)", text: "#7d3c98" };
  if (cat === "কবিতা") return { stripe: "#2980b9", badge: "rgba(41,128,185,0.12)", text: "#1a6fa0" };
  if (cat === "ছোট লেখা") return { stripe: "#27ae60", badge: "rgba(39,174,96,0.12)", text: "#1e8449" };
  return { stripe: "#D4A843", badge: "rgba(212,168,67,0.12)", text: "#b8860b" };
}

// ── Writing Card ─────────────────────────────────────────────────────────────────────────────
function WritingCard({
  writing,
  index,
  onClick,
}: {
  writing: Writing;
  index: number;
  onClick: () => void;
}) {
  const isShort = writing.content.length < 200;
  const preview = writing.content.slice(0, isShort ? writing.content.length : 140);
  const colors = getCategoryColor(writing.category);

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, delay: index * 0.04 }}
      onClick={onClick}
      style={{
        background: "rgba(255,255,255,0.03)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        borderRadius: 14,
        overflow: "hidden",
        cursor: "pointer",
        border: "1px solid rgba(201,168,76,0.1)",
        display: "flex",
        flexDirection: "column",
        boxShadow: "0 4px 20px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.04)",
      }}
      whileHover={{
        y: -5,
        boxShadow: "0 16px 48px rgba(0,0,0,0.5)",
        borderColor: colors.stripe + "99",
      }}
    >
      {/* Category stripe */}
      <div style={{ height: 4, background: colors.stripe, borderRadius: "14px 14px 0 0" }} />

      <div style={{ padding: "20px 22px 22px", flex: 1, display: "flex", flexDirection: "column" }}>
        {/* Category badge */}
        <div style={{ marginBottom: 10 }}>
          <span style={{
            display: "inline-block",
            padding: "3px 12px",
            borderRadius: 50,
            fontSize: "0.68rem",
            fontFamily: "'Noto Sans Bengali', sans-serif",
            background: colors.badge,
            color: colors.text,
            fontWeight: 600,
            letterSpacing: "0.04em",
          }}>
            {writing.category}
          </span>
          {writing.featured && (
            <span style={{
              display: "inline-block", marginLeft: 6,
              padding: "3px 10px", borderRadius: 50,
              fontSize: "0.65rem",
              fontFamily: "'Noto Sans Bengali', sans-serif",
              background: "rgba(212,168,67,0.15)",
              color: "#b8860b", fontWeight: 700,
            }}>★ বিশেষ</span>
          )}
        </div>

        {/* Title */}
        <h3 style={{
          fontFamily: "'Tiro Bangla', serif",
          fontSize: "1.08rem",
          color: "#FDF6EC",
          fontWeight: 700,
          lineHeight: 1.55,
          marginBottom: 10,
        }}>
          {writing.title}
        </h3>

        {/* Preview */}
        <p style={{
          fontFamily: "'Tiro Bangla', serif",
          fontSize: "0.9rem",
          color: "rgba(253,246,236,0.5)",
          lineHeight: 2,
          flex: 1,
          whiteSpace: "pre-line",
        }}>
          {preview}{!isShort && writing.content.length > 140 ? "..." : ""}
        </p>

        {/* Footer */}
        <div style={{
          marginTop: 16,
          paddingTop: 14,
          borderTop: "1px solid rgba(255,255,255,0.06)",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}>
          <span style={{
            fontFamily: "'Noto Sans Bengali', sans-serif",
            fontSize: "0.7rem",
            color: "rgba(253,246,236,0.3)",
            display: "flex",
            alignItems: "center",
            gap: 4,
          }}>
            <Calendar size={11} /> {writing.date}
          </span>
          <span style={{
            fontFamily: "'Noto Sans Bengali', sans-serif",
            fontSize: "0.75rem",
            color: colors.stripe,
            fontWeight: 700,
            display: "flex", alignItems: "center", gap: 4,
          }}>
            পড়ুন <ChevronRight size={13} />
          </span>
        </div>
      </div>
    </motion.div>
  );
}

// ── Modal ─────────────────────────────────────────────────────────────────────────────
function WritingModal({
  writing,
  allWritings,
  onClose,
  onNavigate,
}: {
  writing: Writing;
  allWritings: Writing[];
  onClose: () => void;
  onNavigate: (w: Writing) => void;
}) {
  const [copied, setCopied] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [fontSize, setFontSize] = useState(1.1);

  const currentIndex = allWritings.findIndex((w) => w.id === writing.id);
  const prevWriting = currentIndex > 0 ? allWritings[currentIndex - 1] : null;
  const nextWriting = currentIndex < allWritings.length - 1 ? allWritings[currentIndex + 1] : null;
  const colors = getCategoryColor(writing.category);

  const shareText = `"মাহবুব সরদার সবুজ" লিখেছেন: ${writing.title}`;
  const shareUrl = `${window.location.origin}/writings`;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(`${shareText}\n\n${writing.content.slice(0, 300)}...\n\nপুরো পড়ুন: ${shareUrl}`);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    } catch {
      // fallback
    }
  };

  const handleFacebookShare = () => {
    const fbUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}&quote=${encodeURIComponent(shareText)}`;
    window.open(fbUrl, "_blank", "width=600,height=400");
  };

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title: writing.title, text: shareText, url: shareUrl });
      } catch { /* user cancelled */ }
    } else {
      handleCopy();
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex: 1000,
        background: "rgba(13,27,42,0.8)",
        backdropFilter: "blur(8px)",
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: "1rem",
      }}
    >
      <motion.div
        key={writing.id}
        initial={{ opacity: 0, scale: 0.95, y: 16 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 16 }}
        transition={{ type: "spring", stiffness: 320, damping: 32 }}
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#FEFCF8",
          borderRadius: 20,
          width: "100%",
          maxWidth: 640,
          maxHeight: "90vh",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          boxShadow: "0 40px 100px rgba(13,27,42,0.35), 0 0 0 1px rgba(212,168,67,0.15)",
        }}
      >
        {/* Modal header */}
        <div style={{
          background: `linear-gradient(135deg, #0D1B2A 0%, #1a2f45 100%)`,
          padding: "22px 24px 18px",
          position: "relative",
          borderBottom: `3px solid ${colors.stripe}`,
        }}>
          {/* Top row: close + share */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <span style={{
              display: "inline-flex", alignItems: "center", gap: 6,
              padding: "4px 12px",
              borderRadius: 50,
              fontSize: "0.68rem",
              fontFamily: "'Noto Sans Bengali', sans-serif",
              background: colors.badge,
              color: colors.stripe,
              fontWeight: 700,
              border: `1px solid ${colors.stripe}44`,
            }}>
              {writing.category}
            </span>
            <div style={{ display: "flex", gap: 8 }}>
              {/* Share button */}
              <div style={{ position: "relative" }}>
                <button
                  onClick={() => setShowShare(s => !s)}
                  style={{
                    background: "rgba(255,255,255,0.1)",
                    border: "1px solid rgba(255,255,255,0.15)",
                    borderRadius: 8,
                    width: 34, height: 34,
                    display: "flex", alignItems: "center", justifyContent: "center",
                    cursor: "pointer", color: "#D4A843",
                    transition: "all 0.2s",
                  }}
                  title="শেয়ার করুন"
                >
                  <Share2 size={15} />
                </button>
                {/* Share dropdown */}
                <AnimatePresence>
                  {showShare && (
                    <motion.div
                      initial={{ opacity: 0, y: -8, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: -8, scale: 0.95 }}
                      transition={{ duration: 0.15 }}
                      style={{
                        position: "absolute", top: 40, right: 0,
                        background: "#fff",
                        borderRadius: 12,
                        boxShadow: "0 8px 32px rgba(13,27,42,0.2)",
                        border: "1px solid rgba(13,27,42,0.1)",
                        minWidth: 180,
                        zIndex: 10,
                        overflow: "hidden",
                      }}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <button
                        onClick={() => { handleFacebookShare(); setShowShare(false); }}
                        style={{
                          width: "100%", padding: "11px 16px",
                          display: "flex", alignItems: "center", gap: 10,
                          background: "transparent", border: "none",
                          cursor: "pointer", color: "#1877F2",
                          fontFamily: "'Noto Sans Bengali', sans-serif",
                          fontSize: "0.82rem", fontWeight: 600,
                          borderBottom: "1px solid rgba(13,27,42,0.06)",
                          transition: "background 0.15s",
                        }}
                        onMouseEnter={e => (e.currentTarget.style.background = "rgba(24,119,242,0.06)")}
                        onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
                      >
                        <Facebook size={15} /> Facebook-এ শেয়ার
                      </button>
                      <button
                        onClick={() => { handleCopy(); setShowShare(false); }}
                        style={{
                          width: "100%", padding: "11px 16px",
                          display: "flex", alignItems: "center", gap: 10,
                          background: "transparent", border: "none",
                          cursor: "pointer", color: copied ? "#27ae60" : "#333",
                          fontFamily: "'Noto Sans Bengali', sans-serif",
                          fontSize: "0.82rem", fontWeight: 600,
                          borderBottom: "1px solid rgba(13,27,42,0.06)",
                          transition: "background 0.15s",
                        }}
                        onMouseEnter={e => (e.currentTarget.style.background = "rgba(13,27,42,0.04)")}
                        onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
                      >
                        {copied ? <Check size={15} /> : <Copy size={15} />}
                        {copied ? "কপি হয়েছে!" : "লিংক কপি করুন"}
                      </button>
                      <button
                        onClick={() => { handleNativeShare(); setShowShare(false); }}
                        style={{
                          width: "100%", padding: "11px 16px",
                          display: "flex", alignItems: "center", gap: 10,
                          background: "transparent", border: "none",
                          cursor: "pointer", color: "#555",
                          fontFamily: "'Noto Sans Bengali', sans-serif",
                          fontSize: "0.82rem", fontWeight: 600,
                          transition: "background 0.15s",
                        }}
                        onMouseEnter={e => (e.currentTarget.style.background = "rgba(13,27,42,0.04)")}
                        onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
                      >
                        <Share2 size={15} /> অন্যভাবে শেয়ার
                      </button>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
              {/* Close */}
              <button
                onClick={onClose}
                style={{
                  background: "rgba(255,255,255,0.1)",
                  border: "1px solid rgba(255,255,255,0.15)",
                  borderRadius: 8,
                  width: 34, height: 34,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  cursor: "pointer", color: "rgba(255,255,255,0.7)",
                }}
              >
                <X size={15} />
              </button>
            </div>
          </div>

          {/* Title */}
          <h2 style={{
            fontFamily: "'Tiro Bangla', serif",
            fontSize: "clamp(1.25rem, 3vw, 1.65rem)",
            color: "#FDF6EC",
            lineHeight: 1.45,
            marginBottom: 10,
          }}>
            {writing.title}
          </h2>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <span style={{ color: "rgba(253,246,236,0.45)", fontSize: "0.75rem", fontFamily: "'Noto Sans Bengali', sans-serif", display: "flex", alignItems: "center", gap: 4 }}>
              <Calendar size={11} /> {writing.date}
            </span>
            <span style={{ color: "rgba(253,246,236,0.3)", fontSize: "0.75rem" }}>•</span>
            <span style={{ color: "rgba(253,246,236,0.45)", fontSize: "0.75rem", fontFamily: "'Noto Sans Bengali', sans-serif" }}>
              {currentIndex + 1} / {allWritings.length}
            </span>
          </div>
        </div>

        {/* Font size controls */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "flex-end",
          padding: "8px 20px",
          background: "#F5F3EE",
          borderBottom: "1px solid rgba(13,27,42,0.06)",
          gap: 6,
        }}>
          <span style={{ fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.68rem", color: "#aaa", marginRight: 4 }}>ফন্ট সাইজ:</span>
          <button
            onClick={() => setFontSize(s => Math.max(0.85, s - 0.1))}
            style={{ background: "rgba(13,27,42,0.06)", border: "none", borderRadius: 6, width: 28, height: 28, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: "#555" }}
          >
            <AArrowDown size={13} />
          </button>
          <button
            onClick={() => setFontSize(s => Math.min(1.5, s + 0.1))}
            style={{ background: "rgba(13,27,42,0.06)", border: "none", borderRadius: 6, width: 28, height: 28, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: "#555" }}
          >
            <AArrowUp size={13} />
          </button>
        </div>

        {/* Body */}
        <div style={{ padding: "28px 28px 24px", overflowY: "auto", flex: 1 }}>
          <div style={{
            fontFamily: "'Tiro Bangla', serif",
            fontSize: `${fontSize}rem`,
            color: "#1a1a2e",
            lineHeight: 2.3,
            whiteSpace: "pre-line",
            letterSpacing: "0.01em",
          }}>
            {writing.content}
          </div>

          <div style={{ margin: "28px 0 20px", borderTop: "1px solid rgba(212,168,67,0.25)" }} />

          {/* Author */}
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{
              width: 42, height: 42, borderRadius: "50%",
              background: "linear-gradient(135deg, #0D1B2A, #1a2f45)",
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
              boxShadow: "0 4px 12px rgba(13,27,42,0.2)",
            }}>
              <Feather size={18} color="#D4A843" />
            </div>
            <div>
              <div style={{ fontFamily: "'Tiro Bangla', serif", fontSize: "0.95rem", color: "#0D1B2A", fontWeight: 700 }}>মাহবুব সরদার সবুজ</div>
              <div style={{ fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.72rem", color: "#aaa" }}>Mahbub Sardar Sabuj</div>
            </div>
          </div>
        </div>

        {/* Navigation footer */}
        <div style={{
          display: "flex",
          alignItems: "stretch",
          borderTop: "1px solid rgba(13,27,42,0.08)",
          background: "#F5F3EE",
        }}>
          {/* Prev */}
          <button
            onClick={() => prevWriting && onNavigate(prevWriting)}
            disabled={!prevWriting}
            style={{
              flex: 1,
              padding: "14px 16px",
              background: "transparent",
              border: "none",
              borderRight: "1px solid rgba(13,27,42,0.08)",
              cursor: prevWriting ? "pointer" : "not-allowed",
              display: "flex", alignItems: "center", gap: 8,
              opacity: prevWriting ? 1 : 0.35,
              transition: "background 0.2s",
            }}
            onMouseEnter={e => prevWriting && (e.currentTarget.style.background = "rgba(13,27,42,0.05)")}
            onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
          >
            <ChevronLeft size={16} color="#0D1B2A" />
            <div style={{ textAlign: "left", overflow: "hidden" }}>
              <div style={{ fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.62rem", color: "#aaa", marginBottom: 2 }}>আগের লেখা</div>
              <div style={{ fontFamily: "'Tiro Bangla', serif", fontSize: "0.82rem", color: "#0D1B2A", fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 180 }}>
                {prevWriting?.title}
              </div>
            </div>
          </button>

          {/* Next */}
          <button
            onClick={() => nextWriting && onNavigate(nextWriting)}
            disabled={!nextWriting}
            style={{
              flex: 1,
              padding: "14px 16px",
              background: "transparent",
              border: "none",
              cursor: nextWriting ? "pointer" : "not-allowed",
              display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 8,
              opacity: nextWriting ? 1 : 0.35,
              transition: "background 0.2s",
            }}
            onMouseEnter={e => nextWriting && (e.currentTarget.style.background = "rgba(13,27,42,0.05)")}
            onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
          >
            <div style={{ textAlign: "right", overflow: "hidden" }}>
              <div style={{ fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.62rem", color: "#aaa", marginBottom: 2 }}>পরের লেখা</div>
              <div style={{ fontFamily: "'Tiro Bangla', serif", fontSize: "0.82rem", color: "#0D1B2A", fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 180 }}>
                {nextWriting?.title}
              </div>
            </div>
            <ChevronRight size={16} color="#0D1B2A" />
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
}

// ── Main Writings Page ────────────────────────────────────────────────────────
export default function Writings() {
  const [activeCategory, setActiveCategory] = useState("all");
  const [selectedWriting, setSelectedWriting] = useState<typeof writings[0] | null>(null);
  const [searchQuery, setSearchQuery] = useState("");

  const filtered = writings.filter((w) => {
    const matchCat = activeCategory === "all" || w.category === activeCategory;
    const matchSearch = searchQuery === "" ||
      w.title.includes(searchQuery) ||
      w.content.includes(searchQuery);
    return matchCat && matchSearch;
  });

  const featured = writings.find((w) => w.featured);

  const writingsJsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "CollectionPage",
        "name": "লেখালেখি | মাহবুব সরদার সবুজ",
        "url": "https://www.mahbubsardarsabuj.com/writings",
        "inLanguage": "bn-BD",
        "description": "মাহবুব সরদার সবুজের কবিতা, ছোট লেখা, ভালোবাসা, জীবনদর্শন ও বিচ্ছেদভিত্তিক লেখার সংগ্রহ।"
      },
      {
        "@type": "Person",
        "name": "Mahbub Sardar Sabuj",
        "alternateName": "মাহবুব সরদার সবুজ",
        "url": "https://www.mahbubsardarsabuj.com/"
      }
    ]
  };

  return (
    <div style={{ minHeight: "100vh", background: "#060E1A" }}>
      <Seo
        title="বাংলা কবিতা ও লেখা | মাহবুব সরদার সবুজ"
        description="মাহবুব সরদার সবুজের ১৯০+ বাংলা কবিতা ও লেখার সংগ্রহ। ভালোবাসার কবিতা, বিচ্ছেদের কবিতা, জীবনদর্শনের ছোট লেখা — সবই এক জায়গায়। লক্ষাধিক পাঠকের প্রিয় বাংলা সাহিত্যের সংগ্রহ।"
        path="/writings"
        keywords="বাংলা কবিতা, ভালোবাসার কবিতা, বিচ্ছেদের কবিতা, জীবনদর্শন, মাহবুব সরদার সবুজ লেখালেখি, Mahbub Sardar Sabuj writings, বাংলা সাহিত্য, বাংলা ছোট গল্প, বাংলা প্রবন্ধ, মনের কথা, ভালোবাসার লেখা"
        jsonLd={writingsJsonLd}
      />
      <Navbar />

      {/* Page Hero */}
      <div style={{
        background: "linear-gradient(135deg, #0D1B2A 0%, #1a2f45 60%, #0D1B2A 100%)",
        paddingTop: 100,
        paddingBottom: 60,
        position: "relative",
        overflow: "hidden",
      }}>
        <div style={{
          position: "absolute", inset: 0,
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23D4A843' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
        }} />

        <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 1.5rem", position: "relative" }}>
          <Link href="/">
            <motion.span
              whileHover={{ x: -4 }}
              style={{
                display: "inline-flex", alignItems: "center", gap: 6,
                color: "rgba(253,246,236,0.5)", fontSize: "0.85rem",
                fontFamily: "'Noto Sans Bengali', sans-serif",
                cursor: "pointer", marginBottom: 24, textDecoration: "none",
              }}
            >
              <ArrowLeft size={15} /> হোমে ফিরুন
            </motion.span>
          </Link>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
              <Feather size={28} color="#D4A843" />
              <span style={{ color: "#D4A843", fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.85rem", letterSpacing: "0.12em", textTransform: "uppercase" }}>
                DAILY WRITINGS
              </span>
            </div>
            <h1 style={{
              fontFamily: "'Tiro Bangla', serif",
              fontSize: "clamp(2rem, 5vw, 3.5rem)",
              color: "#FDF6EC",
              lineHeight: 1.3,
              marginBottom: 16,
            }}>
              লেখালেখি
            </h1>
            <p style={{
              fontFamily: "'Noto Sans Bengali', sans-serif",
              color: "rgba(253,246,236,0.65)",
              fontSize: "1rem",
              maxWidth: 500,
              lineHeight: 1.8,
            }}>
              প্রতিদিনের অনুভূতি, কবিতা, গল্প ও ভাবনা — মাহবুব সরদার সবুজের কলম থেকে।
            </p>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            style={{ display: "flex", gap: 32, marginTop: 32, flexWrap: "wrap" }}
          >
            {[
              { icon: <BookOpen size={16} />, label: "মোট লেখা", value: `${writings.length}+` },
              { icon: <Star size={16} />, label: "প্রকাশিত বই", value: "১টি" },
              { icon: <Heart size={16} />, label: "পাঠক", value: "লক্ষাধিক" },
            ].map((stat, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ color: "#D4A843" }}>{stat.icon}</span>
                <div>
                  <div style={{ color: "#FDF6EC", fontFamily: "'Tiro Bangla', serif", fontSize: "1.1rem", fontWeight: 700 }}>{stat.value}</div>
                  <div style={{ color: "rgba(253,246,236,0.5)", fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.72rem" }}>{stat.label}</div>
                </div>
              </div>
            ))}
          </motion.div>
        </div>
      </div>

      {/* Search + Category Tabs */}
      <div style={{
        background: "rgba(6,14,26,0.85)",
        backdropFilter: "blur(16px)",
        WebkitBackdropFilter: "blur(16px)",
        borderBottom: "1px solid rgba(201,168,76,0.1)",
        position: "sticky",
        top: 70,
        zIndex: 40,
      }}>
        <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 1.5rem" }}>
          {/* Search */}
          <div style={{ paddingTop: 12, paddingBottom: 4 }}>
            <div style={{
              display: "flex", alignItems: "center", gap: 8,
              background: "rgba(255,255,255,0.05)",
              borderRadius: 8, padding: "8px 14px",
              maxWidth: 320,
              border: "1px solid rgba(201,168,76,0.15)",
            }}>
              <Search size={14} color="#C9A84C" />
              <input
                type="text"
                placeholder="লেখা খুঁজুন..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                style={{
                  border: "none", background: "transparent", outline: "none",
                  fontFamily: "'Noto Sans Bengali', sans-serif",
                  fontSize: "0.85rem", color: "#FDF6EC", width: "100%",
                }}
              />
            </div>
          </div>
          {/* Categories */}
          <div style={{ display: "flex", gap: 4, overflowX: "auto", padding: "8px 0 12px", scrollbarWidth: "none" }}>
            {CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                style={{
                  padding: "7px 16px",
                  borderRadius: 50,
                  border: "none",
                  cursor: "pointer",
                  fontFamily: "'Noto Sans Bengali', sans-serif",
                  fontSize: "0.83rem",
                  whiteSpace: "nowrap",
                  transition: "all 0.3s",
                  background: activeCategory === cat.id ? "rgba(201,168,76,0.15)" : "transparent",
                  color: activeCategory === cat.id ? "#D4A843" : "rgba(253,246,236,0.45)",
                  fontWeight: activeCategory === cat.id ? 700 : 400,
                }}
              >
                {cat.icon} {cat.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "2.5rem 1.5rem 4rem" }}>

        {/* Featured Post */}
        {activeCategory === "all" && !searchQuery && featured && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            onClick={() => setSelectedWriting(featured)}
            style={{
              background: "linear-gradient(135deg, #0D1B2A 0%, #1a2f45 100%)",
              borderRadius: 16,
              padding: "clamp(24px, 4vw, 44px)",
              marginBottom: 40,
              cursor: "pointer",
              position: "relative",
              overflow: "hidden",
            }}
            whileHover={{ scale: 1.005, boxShadow: "0 20px 60px rgba(13,27,42,0.3)" }}
          >
            <div style={{
              position: "absolute", top: -30, right: -30,
              width: 200, height: 200, borderRadius: "50%",
              background: "rgba(212,168,67,0.06)",
            }} />
            <div style={{ position: "relative" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
                <Star size={14} color="#D4A843" fill="#D4A843" />
                <span style={{ color: "#D4A843", fontFamily: "'Noto Sans Bengali', sans-serif", fontSize: "0.75rem", letterSpacing: "0.1em" }}>
                  বিশেষ লেখা
                </span>
              </div>
              <h2 style={{
                fontFamily: "'Tiro Bangla', serif",
                fontSize: "clamp(1.4rem, 3vw, 2rem)",
                color: "#FDF6EC",
                lineHeight: 1.4,
                marginBottom: 16,
              }}>
                {featured.title}
              </h2>
              <p style={{
                fontFamily: "'Tiro Bangla', serif",
                color: "rgba(253,246,236,0.7)",
                fontSize: "1rem",
                lineHeight: 2,
                maxWidth: 600,
                whiteSpace: "pre-line",
              }}>
                {featured.content.slice(0, 200)}...
              </p>
              <div style={{ marginTop: 20 }}>
                <span style={{
                  display: "inline-flex", alignItems: "center", gap: 6,
                  color: "#D4A843",
                  fontFamily: "'Noto Sans Bengali', sans-serif",
                  fontSize: "0.85rem", fontWeight: 600,
                }}>
                  পুরো লেখা পড়ুন →
                </span>
              </div>
            </div>
          </motion.div>
        )}

        {/* Results count */}
        <div style={{
          fontFamily: "'Noto Sans Bengali', sans-serif",
          fontSize: "0.8rem",
          color: "#888",
          marginBottom: 20,
        }}>
          <span style={{ color: "rgba(201,168,76,0.6)" }}>{filtered.length}টি লেখা পাওয়া গেছে</span>
        </div>

        {/* Grid */}
        {filtered.length > 0 ? (
          <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: 20,
          }}>
            {filtered.map((writing, i) => (
              <WritingCard
                key={writing.id}
                writing={writing}
                index={i}
                onClick={() => setSelectedWriting(writing)}
              />
            ))}
          </div>
        ) : (
          <div style={{
            textAlign: "center",
            padding: "60px 20px",
            color: "rgba(253,246,236,0.4)",
            fontFamily: "'Noto Sans Bengali', sans-serif",
          }}>
            <Feather size={40} color="rgba(201,168,76,0.3)" style={{ marginBottom: 16 }} />
            <p>কোনো লেখা পাওয়া যায়নি।</p>
          </div>
        )}
      </div>

      {/* Modal */}
      <AnimatePresence>
        {selectedWriting && (
          <WritingModal
            writing={selectedWriting}
            allWritings={filtered}
            onClose={() => setSelectedWriting(null)}
            onNavigate={(w) => setSelectedWriting(w)}
          />
        )}
      </AnimatePresence>
    </div>
  );
}
